ALTER TABLE public.notification_outbox ADD COLUMN lease_until timestamptz, ADD COLUMN manual_retry boolean NOT NULL DEFAULT false;
ALTER TABLE public.notification_contacts ADD COLUMN lease_until timestamptz;
CREATE OR REPLACE FUNCTION public.save_notification_phone(p_phone text) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR (p_phone<>'' AND p_phone !~ '^\+?[0-9 ()-]{7,30}$') THEN RAISE EXCEPTION 'Invalid phone or session'; END IF; UPDATE public.profiles SET phone=nullif(p_phone,'') WHERE id=auth.uid(); END; $$;
REVOKE ALL ON FUNCTION public.save_notification_phone(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_notification_phone(text) TO authenticated;
CREATE OR REPLACE FUNCTION public.notification_claim() RETURNS SETOF public.notification_outbox LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ UPDATE public.notification_outbox SET lease_until=now()+interval '5 minutes' WHERE id IN (SELECT id FROM public.notification_outbox WHERE status IN ('pending','failed','awaiting_credentials') AND next_attempt_at<=now() AND (lease_until IS NULL OR lease_until<now()) AND (automatic_tries<3 OR manual_retry) ORDER BY next_attempt_at LIMIT 25 FOR UPDATE SKIP LOCKED) RETURNING *; $$;
CREATE OR REPLACE FUNCTION public.notification_contact_claim(p_channel text,p_contact text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.notification_contacts(channel,contact) VALUES(p_channel,p_contact) ON CONFLICT(channel,contact) DO NOTHING; UPDATE public.notification_contacts SET lease_until=now()+interval '2 minutes' WHERE channel=p_channel AND contact=p_contact AND failures<5 AND (lease_until IS NULL OR lease_until<now()); RETURN FOUND; END; $$;
CREATE OR REPLACE FUNCTION public.notification_contact_result(p_channel text,p_contact text,p_success boolean) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ UPDATE public.notification_contacts SET failures=CASE WHEN p_success THEN failures ELSE failures+1 END,lease_until=NULL WHERE channel=p_channel AND contact=p_contact; $$;
REVOKE ALL ON FUNCTION public.notification_claim(),public.notification_contact_claim(text,text),public.notification_contact_result(text,text,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.notification_claim(),public.notification_contact_claim(text,text),public.notification_contact_result(text,text,boolean) TO service_role;
CREATE EXTENSION IF NOT EXISTS pg_net;
CREATE OR REPLACE FUNCTION public.notification_wake() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM net.http_post(url:='https://tycaownqbhtexkvdkuor.supabase.co/functions/v1/process-notifications',headers:='{"Content-Type":"application/json","apikey":"sb_publishable_NbSNBjDVVFnAeW40IemXOw_jrZmujd7"}'::jsonb,body:='{}'::jsonb); END; $$;
CREATE OR REPLACE FUNCTION public.notification_schedule_next() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t timestamptz; j bigint; BEGIN
PERFORM pg_advisory_xact_lock(761420);
SELECT jobid INTO j FROM cron.job WHERE jobname='notification-retry'; IF j IS NOT NULL THEN PERFORM cron.unschedule(j); END IF;
SELECT min(greatest(next_attempt_at,now()+interval '1 minute',coalesce(lease_until,now()))) INTO t FROM public.notification_outbox WHERE status IN ('pending','failed','awaiting_credentials') AND (automatic_tries<3 OR manual_retry);
IF t IS NOT NULL THEN PERFORM cron.schedule('notification-retry',to_char(t AT TIME ZONE 'UTC','MI HH24 DD MM')||' *','SELECT public.notification_wake(); SELECT public.notification_schedule_next();'); END IF;
END; $$;
CREATE OR REPLACE FUNCTION public.notification_enqueue_wake() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' OR (NEW.status='pending' AND OLD.status IS DISTINCT FROM NEW.status) THEN PERFORM public.notification_wake(); PERFORM public.notification_schedule_next(); END IF; RETURN NEW; END; $$;
CREATE TRIGGER notification_enqueue_wake AFTER INSERT OR UPDATE OF status ON public.notification_outbox FOR EACH ROW EXECUTE FUNCTION public.notification_enqueue_wake();
REVOKE ALL ON FUNCTION public.notification_wake(),public.notification_schedule_next(),public.notification_enqueue_wake() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.notification_schedule_next() TO service_role;
CREATE OR REPLACE FUNCTION notification_private.retry_notification(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.profiles; BEGIN
IF NOT public.is_notification_staff() OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND is_active) THEN RAISE EXCEPTION 'Staff access required'; END IF;
SELECT pr.* INTO p FROM public.profiles pr JOIN public.notification_outbox n ON n.user_id=pr.id WHERE n.id=p_id AND n.status IN ('failed','blocked','awaiting_credentials'); IF NOT FOUND THEN RAISE EXCEPTION 'Not retryable'; END IF;
IF NOT EXISTS(SELECT 1 FROM (VALUES('email',lower(trim(coalesce(p.email,'')))),('text',regexp_replace(coalesce(p.phone,''),'[^+0-9]','','g'))) v(channel,contact) LEFT JOIN public.notification_contacts c ON c.channel=v.channel AND c.contact=v.contact WHERE v.contact<>'' AND coalesce(c.failures,0)<5 AND (p.notification_method='both' OR p.notification_method=v.channel)) THEN RAISE EXCEPTION 'Update blocked contact before retrying'; END IF;
UPDATE public.notification_outbox SET status='pending',next_attempt_at=now(),manual_retry=true WHERE id=p_id; END; $$;